-- Canonical PostgreSQL bootstrap. Generated from the validated canonical schema.
-- OpsCore PostgreSQL canonical schema generated from the runtime SQLite schema.
-- Purpose: schema parity / buyer handoff.
-- This file does NOT claim runtime production certification by itself.
-- Generated from backend/src/db.js; verify with scripts/postgres-parity-check.js.

CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','admin','manager','member','viewer')), created_at TEXT NOT NULL, PRIMARY KEY(user_id, organization_id));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','manager','member','viewer')), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, accepted_at TEXT, invited_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, email TEXT, phone TEXT, external_ref TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sites (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, name TEXT NOT NULL, address TEXT, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, geojson TEXT, external_ref TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)));
CREATE TABLE IF NOT EXISTS work_orders (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, number TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','blocked','completed','cancelled')), priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')), customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, site_id TEXT REFERENCES sites(id) ON DELETE SET NULL, assigned_to TEXT REFERENCES users(id) ON DELETE SET NULL, team_name TEXT, due_at TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completion_policy_id TEXT, completion_policy_version INTEGER);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, asset_type TEXT NOT NULL, external_ref TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','retired')), site_id TEXT REFERENCES sites(id) ON DELETE SET NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS asset_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, work_order_id TEXT REFERENCES work_orders(id) ON DELETE SET NULL, event_type TEXT NOT NULL CHECK(event_type IN ('installed','inspection','service','failure','repair','retired','note')), occurred_at TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS locations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, geojson TEXT, created_at TEXT NOT NULL, CHECK((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)));
CREATE TABLE IF NOT EXISTS activity_log (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, event_type TEXT NOT NULL, message TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT REFERENCES work_orders(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, storage_provider TEXT NOT NULL CHECK(storage_provider IN ('local')), storage_key TEXT NOT NULL UNIQUE, file_name TEXT NOT NULL, media_type TEXT NOT NULL, bytes BIGINT NOT NULL CHECK(bytes >= 0), sha256 TEXT NOT NULL, uploaded_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, channel TEXT NOT NULL CHECK(channel IN ('in_app','email','webhook')), event_type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','accepted','delivered','failed','read')), created_at TEXT NOT NULL, read_at TEXT);
CREATE TABLE IF NOT EXISTS webhook_endpoints (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, url TEXT NOT NULL, secret_hash TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id TEXT PRIMARY KEY, endpoint_id TEXT NOT NULL REFERENCES webhook_endpoints(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, event_type TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','accepted','delivered','failed')), attempts BIGINT NOT NULL DEFAULT 0, response_code BIGINT, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS integration_outbox (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, event_key TEXT NOT NULL, event_type TEXT NOT NULL, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','processing','delivered','failed')), attempts BIGINT NOT NULL DEFAULT 0, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, delivered_at TEXT, UNIQUE(organization_id,event_key));
CREATE INDEX IF NOT EXISTS idx_integration_outbox_status_created ON integration_outbox(organization_id,status,created_at);
CREATE TABLE IF NOT EXISTS evidence_uploads (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, file_name TEXT NOT NULL, media_type TEXT NOT NULL, total_bytes BIGINT NOT NULL CHECK(total_bytes > 0), expected_sha256 TEXT NOT NULL, received_bytes BIGINT NOT NULL DEFAULT 0, chunk_size BIGINT NOT NULL, total_chunks BIGINT NOT NULL, status TEXT NOT NULL CHECK(status IN ('initiated','uploading','ready','committed','failed')), storage_key TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, committed_attachment_id TEXT REFERENCES attachments(id) ON DELETE SET NULL, last_error TEXT);
CREATE INDEX IF NOT EXISTS idx_evidence_uploads_org_wo_status ON evidence_uploads(organization_id,work_order_id,status);
CREATE TABLE IF NOT EXISTS evidence_upload_chunks (upload_id TEXT NOT NULL REFERENCES evidence_uploads(id) ON DELETE CASCADE, chunk_index BIGINT NOT NULL, bytes BIGINT NOT NULL, sha256 TEXT NOT NULL, storage_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, PRIMARY KEY(upload_id,chunk_index));
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, organization_id TEXT, actor_user_id TEXT, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pdf_signatures (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, document_type TEXT NOT NULL, document_id TEXT NOT NULL, document_sha256 TEXT NOT NULL, algorithm TEXT NOT NULL, signer_id TEXT NOT NULL, signature_base64url TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(organization_id,document_type,document_id,document_sha256));
CREATE INDEX IF NOT EXISTS idx_pdf_signatures_doc ON pdf_signatures(organization_id,document_type,document_id,created_at);
CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, key_prefix TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE, scopes_json TEXT NOT NULL DEFAULT '[]', expires_at TEXT, revoked_at TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, last_used_at TEXT);
CREATE TABLE IF NOT EXISTS rate_limit_buckets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, api_key_id TEXT REFERENCES api_keys(id) ON DELETE CASCADE, bucket_key TEXT NOT NULL, window_start TEXT NOT NULL, requests BIGINT NOT NULL DEFAULT 0, UNIQUE(organization_id, bucket_key, window_start));
CREATE TABLE IF NOT EXISTS entitlements (organization_id TEXT PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, plan TEXT NOT NULL, limits_json TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage_counters (organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, metric TEXT NOT NULL, period_start TEXT NOT NULL, quantity BIGINT NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY(organization_id, metric, period_start));
CREATE TABLE IF NOT EXISTS stripe_billing (organization_id TEXT PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, stripe_customer_id TEXT UNIQUE, stripe_subscription_id TEXT UNIQUE, status TEXT NOT NULL, plan TEXT NOT NULL, price_id TEXT, current_period_end TEXT, last_event_created BIGINT NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stripe_events (event_id TEXT PRIMARY KEY, event_type TEXT NOT NULL, organization_id TEXT, created_at TEXT NOT NULL, event_created BIGINT NOT NULL DEFAULT 0, payload_sha256 TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_stripe_events_org_created ON stripe_events(organization_id, created_at);
CREATE TABLE IF NOT EXISTS custom_fields (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, field_key TEXT NOT NULL, label TEXT NOT NULL, field_type TEXT NOT NULL CHECK(field_type IN ('text','number','boolean','date','select')), options_json TEXT NOT NULL DEFAULT '[]', created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(organization_id, entity_type, field_key));
CREATE TABLE IF NOT EXISTS custom_field_values (organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, field_id TEXT NOT NULL REFERENCES custom_fields(id) ON DELETE CASCADE, value_text TEXT, updated_at TEXT NOT NULL, PRIMARY KEY(organization_id, entity_type, entity_id, field_id));
CREATE TABLE IF NOT EXISTS saved_views (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, entity_type TEXT NOT NULL, filters_json TEXT NOT NULL DEFAULT '{}', columns_json TEXT NOT NULL DEFAULT '[]', created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deleted_records (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, deleted_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, deleted_at TEXT NOT NULL, restored_at TEXT);
CREATE TABLE IF NOT EXISTS password_reset_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);



CREATE TABLE IF NOT EXISTS workflow_definitions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, entity_type TEXT NOT NULL CHECK(entity_type='work_order'), statuses_json TEXT NOT NULL, transitions_json TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS workflow_transition_log (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, workflow_id TEXT NOT NULL REFERENCES workflow_definitions(id) ON DELETE CASCADE, entity_id TEXT NOT NULL, from_status TEXT, to_status TEXT NOT NULL, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, reason TEXT, workflow_version BIGINT, decision_hash TEXT);
CREATE TABLE IF NOT EXISTS workflow_versions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, workflow_id TEXT NOT NULL REFERENCES workflow_definitions(id) ON DELETE CASCADE, version BIGINT NOT NULL, snapshot_json TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(workflow_id,version));
CREATE TABLE IF NOT EXISTS completion_policies (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, work_type TEXT NOT NULL DEFAULT '*', require_customer_signoff BIGINT NOT NULL DEFAULT 0 CHECK(require_customer_signoff IN (0,1)), require_safety_acknowledgement BIGINT NOT NULL DEFAULT 0 CHECK(require_safety_acknowledgement IN (0,1)), require_procedure_completion BIGINT NOT NULL DEFAULT 0 CHECK(require_procedure_completion IN (0,1)), require_evidence BIGINT NOT NULL DEFAULT 0 CHECK(require_evidence IN (0,1)), require_first_time_right BIGINT NOT NULL DEFAULT 0 CHECK(require_first_time_right IN (0,1)), min_evidence_count INTEGER NOT NULL DEFAULT 0 CHECK(min_evidence_count >= 0), active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,work_type));
CREATE TABLE IF NOT EXISTS completion_policy_versions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, completion_policy_id TEXT NOT NULL REFERENCES completion_policies(id) ON DELETE CASCADE, version INTEGER NOT NULL, snapshot_json TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(completion_policy_id,version));
CREATE INDEX IF NOT EXISTS idx_completion_policy_versions_org ON completion_policy_versions(organization_id,completion_policy_id,version);
CREATE INDEX IF NOT EXISTS idx_completion_policy_org ON completion_policies(organization_id,active,work_type);

CREATE TABLE IF NOT EXISTS escalation_rules (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, trigger_type TEXT NOT NULL CHECK(trigger_type IN ('sla_at_risk','sla_breached','stuck_work_order')), threshold_minutes BIGINT NOT NULL DEFAULT 0 CHECK(threshold_minutes >= 0), priority TEXT, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS escalations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, rule_id TEXT REFERENCES escalation_rules(id) ON DELETE SET NULL, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, trigger_type TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('warning','critical')), status TEXT NOT NULL CHECK(status IN ('open','acknowledged','resolved')), reason TEXT NOT NULL, created_at TEXT NOT NULL, acknowledged_at TEXT, resolved_at TEXT, UNIQUE(organization_id,work_order_id,trigger_type,status));
CREATE TABLE IF NOT EXISTS procedure_definitions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, work_type TEXT NOT NULL, version BIGINT NOT NULL DEFAULT 1, steps_json TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS procedure_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, procedure_id TEXT NOT NULL REFERENCES procedure_definitions(id) ON DELETE RESTRICT, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, status TEXT NOT NULL CHECK(status IN ('in_progress','completed','failed')), completed_steps BIGINT NOT NULL DEFAULT 0, evidence_json TEXT NOT NULL DEFAULT '[]', started_at TEXT NOT NULL, completed_at TEXT);
CREATE INDEX IF NOT EXISTS idx_workflow_org ON workflow_definitions(organization_id,active);
CREATE INDEX IF NOT EXISTS idx_escalation_org ON escalations(organization_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_procedure_org ON procedure_definitions(organization_id,active);
CREATE INDEX IF NOT EXISTS idx_procedure_runs_wo ON procedure_runs(organization_id,work_order_id,started_at);

CREATE INDEX IF NOT EXISTS idx_memberships_org ON memberships(organization_id);
CREATE INDEX IF NOT EXISTS idx_work_orders_org_status ON work_orders(organization_id, status);
CREATE INDEX IF NOT EXISTS idx_assets_org ON assets(organization_id);
CREATE INDEX IF NOT EXISTS idx_asset_events_org_asset ON asset_events(organization_id,asset_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_asset_events_wo ON asset_events(organization_id,work_order_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_sites_org ON sites(organization_id);
CREATE INDEX IF NOT EXISTS idx_locations_org ON locations(organization_id);
CREATE INDEX IF NOT EXISTS idx_activity_entity ON activity_log(organization_id, entity_type, entity_id, created_at);
CREATE INDEX IF NOT EXISTS idx_comments_wo ON comments(organization_id, work_order_id, created_at);
CREATE INDEX IF NOT EXISTS idx_attachments_entity ON attachments(organization_id, entity_type, entity_id, created_at);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(organization_id, user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_endpoint ON webhook_deliveries(organization_id, endpoint_id, created_at);
CREATE INDEX IF NOT EXISTS idx_audit_org_created ON audit_log(organization_id, created_at);
CREATE INDEX IF NOT EXISTS idx_api_keys_org ON api_keys(organization_id, revoked_at);
CREATE INDEX IF NOT EXISTS idx_usage_org_metric ON usage_counters(organization_id, metric, period_start);
CREATE INDEX IF NOT EXISTS idx_custom_fields_org ON custom_fields(organization_id, entity_type);
CREATE INDEX IF NOT EXISTS idx_saved_views_org ON saved_views(organization_id, entity_type);
CREATE INDEX IF NOT EXISTS idx_deleted_records_org ON deleted_records(organization_id, entity_type, deleted_at);

CREATE TABLE IF NOT EXISTS technician_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, working_from_lat DOUBLE PRECISION, working_from_lon DOUBLE PRECISION, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK((working_from_lat IS NULL AND working_from_lon IS NULL) OR (working_from_lat BETWEEN -90 AND 90 AND working_from_lon BETWEEN -180 AND 180)));
CREATE TABLE IF NOT EXISTS technician_skills (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill TEXT NOT NULL, level BIGINT NOT NULL DEFAULT 1 CHECK(level BETWEEN 1 AND 5), created_at TEXT NOT NULL, UNIQUE(organization_id,user_id,skill));
CREATE TABLE IF NOT EXISTS sla_policies (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('low','normal','high','urgent')), response_minutes BIGINT, resolution_minutes BIGINT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,priority));
CREATE TABLE IF NOT EXISTS work_order_sla (work_order_id TEXT PRIMARY KEY REFERENCES work_orders(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, policy_id TEXT REFERENCES sla_policies(id) ON DELETE SET NULL, due_at TEXT, breached_at TEXT, status TEXT NOT NULL CHECK(status IN ('on_track','at_risk','breached','met')), started_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS appointments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, technician_id TEXT REFERENCES users(id) ON DELETE SET NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('scheduled','confirmed','en_route','completed','cancelled','no_show')), customer_confirmed_at TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, checkin_latitude DOUBLE PRECISION, checkin_longitude DOUBLE PRECISION, checkin_accuracy_m DOUBLE PRECISION, checked_in_at TEXT, checked_in_by TEXT REFERENCES users(id) ON DELETE SET NULL, CHECK(end_at > start_at), CHECK(checkin_latitude IS NULL OR checkin_latitude BETWEEN -90 AND 90), CHECK(checkin_longitude IS NULL OR checkin_longitude BETWEEN -180 AND 180), CHECK(checkin_accuracy_m IS NULL OR checkin_accuracy_m >= 0), UNIQUE(work_order_id,start_at));
CREATE TABLE IF NOT EXISTS parts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, sku TEXT NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT 'unit', active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,sku));
CREATE TABLE IF NOT EXISTS inventory_locations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS inventory_stock (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, part_id TEXT NOT NULL REFERENCES parts(id) ON DELETE CASCADE, location_id TEXT NOT NULL REFERENCES inventory_locations(id) ON DELETE CASCADE, quantity BIGINT NOT NULL DEFAULT 0 CHECK(quantity >= 0), updated_at TEXT NOT NULL, UNIQUE(organization_id,part_id,location_id));
CREATE TABLE IF NOT EXISTS work_order_parts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, part_id TEXT NOT NULL REFERENCES parts(id) ON DELETE RESTRICT, location_id TEXT NOT NULL REFERENCES inventory_locations(id) ON DELETE RESTRICT, quantity BIGINT NOT NULL CHECK(quantity > 0), status TEXT NOT NULL CHECK(status IN ('reserved','consumed','returned')), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS portal_access_tokens (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, last_used_at TEXT);
CREATE TABLE IF NOT EXISTS customer_signoffs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, signer_name TEXT NOT NULL, acknowledgement TEXT NOT NULL, signed_at TEXT NOT NULL, ip_hint TEXT, signature_sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS org_units (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, parent_id TEXT REFERENCES org_units(id) ON DELETE RESTRICT, name TEXT NOT NULL, unit_type TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS unit_memberships (organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, unit_id TEXT NOT NULL REFERENCES org_units(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, unit_role TEXT NOT NULL CHECK(unit_role IN ('head','lead','member','viewer')), created_at TEXT NOT NULL, PRIMARY KEY(unit_id,user_id));
CREATE INDEX IF NOT EXISTS idx_org_units_parent ON org_units(organization_id,parent_id);
CREATE INDEX IF NOT EXISTS idx_unit_memberships_user ON unit_memberships(organization_id,user_id);
CREATE TABLE IF NOT EXISTS idempotency_records (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, operation TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, response_status INTEGER NOT NULL, response_json JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,actor_user_id,operation,idempotency_key));
CREATE TABLE IF NOT EXISTS login_throttle (throttle_key TEXT PRIMARY KEY, window_start BIGINT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, locked_until BIGINT NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_idempotency_org_actor ON idempotency_records(organization_id,actor_user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_login_throttle_updated ON login_throttle(updated_at);
CREATE TABLE IF NOT EXISTS sync_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, client_event_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, operation TEXT NOT NULL CHECK(operation IN ('status_update','comment','appointment_on_my_way','appointment_checkin','signoff','attachment')), payload_json TEXT NOT NULL, applied_at TEXT NOT NULL, UNIQUE(organization_id,actor_user_id,client_event_id));
CREATE TABLE IF NOT EXISTS sync_blocks (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, block_id TEXT NOT NULL, block_hash TEXT NOT NULL, event_count BIGINT NOT NULL CHECK(event_count >= 0), first_client_event_id TEXT, last_client_event_id TEXT, received_at TEXT NOT NULL, UNIQUE(organization_id,actor_user_id,block_id));
CREATE INDEX IF NOT EXISTS idx_sync_blocks_org_actor_received ON sync_blocks(organization_id,actor_user_id,received_at);

CREATE INDEX IF NOT EXISTS idx_tech_profiles_org ON technician_profiles(organization_id,active);
CREATE INDEX IF NOT EXISTS idx_tech_skills_org_user ON technician_skills(organization_id,user_id);
CREATE INDEX IF NOT EXISTS idx_sla_org_priority ON sla_policies(organization_id,priority);
CREATE INDEX IF NOT EXISTS idx_work_order_sla_org_status ON work_order_sla(organization_id,status,due_at);
CREATE INDEX IF NOT EXISTS idx_appt_org_tech_time ON appointments(organization_id,technician_id,start_at,end_at);
CREATE INDEX IF NOT EXISTS idx_parts_org ON parts(organization_id,sku);
CREATE INDEX IF NOT EXISTS idx_inventory_org_location ON inventory_stock(organization_id,location_id);
CREATE INDEX IF NOT EXISTS idx_wop_org_wo ON work_order_parts(organization_id,work_order_id,status);
CREATE INDEX IF NOT EXISTS idx_portal_tokens_org_customer ON portal_access_tokens(organization_id,customer_id,revoked_at);
CREATE INDEX IF NOT EXISTS idx_signoffs_org_wo ON customer_signoffs(organization_id,work_order_id,signed_at);
CREATE INDEX IF NOT EXISTS idx_sync_org_actor ON sync_events(organization_id,actor_user_id,applied_at);
CREATE TABLE IF NOT EXISTS operational_financial_settings (organization_id TEXT PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, currency TEXT NOT NULL DEFAULT 'USD', labor_cost_per_hour DOUBLE PRECISION, updated_at TEXT NOT NULL, CHECK(labor_cost_per_hour IS NULL OR labor_cost_per_hour >= 0));
CREATE TABLE IF NOT EXISTS work_order_financials (work_order_id TEXT PRIMARY KEY REFERENCES work_orders(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, labor_hours DOUBLE PRECISION, revenue DOUBLE PRECISION, repeat_visit BIGINT NOT NULL DEFAULT 0 CHECK(repeat_visit IN (0,1)), updated_at TEXT NOT NULL, CHECK(labor_hours IS NULL OR labor_hours >= 0), CHECK(revenue IS NULL OR revenue >= 0));
CREATE TABLE IF NOT EXISTS estimates (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, work_order_id TEXT REFERENCES work_orders(id) ON DELETE SET NULL, number TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','sent','accepted','rejected','expired','cancelled')), currency TEXT NOT NULL, subtotal DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(subtotal >= 0), discount DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(discount >= 0), tax DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(tax >= 0), total DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(total >= 0), valid_until TEXT, notes TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,number));
CREATE TABLE IF NOT EXISTS estimate_lines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, estimate_id TEXT NOT NULL REFERENCES estimates(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity DOUBLE PRECISION NOT NULL CHECK(quantity > 0), unit_price DOUBLE PRECISION NOT NULL CHECK(unit_price >= 0), line_total DOUBLE PRECISION NOT NULL CHECK(line_total >= 0), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, work_order_id TEXT REFERENCES work_orders(id) ON DELETE SET NULL, estimate_id TEXT REFERENCES estimates(id) ON DELETE SET NULL, number TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','issued','partially_paid','paid','void','overdue')), currency TEXT NOT NULL, subtotal DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(subtotal >= 0), discount DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(discount >= 0), tax DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(tax >= 0), total DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(total >= 0), amount_paid DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(amount_paid >= 0), due_at TEXT, notes TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,number));
CREATE TABLE IF NOT EXISTS invoice_lines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity DOUBLE PRECISION NOT NULL CHECK(quantity > 0), unit_price DOUBLE PRECISION NOT NULL CHECK(unit_price >= 0), line_total DOUBLE PRECISION NOT NULL CHECK(line_total >= 0), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_estimates_org_customer ON estimates(organization_id,customer_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_estimate_lines_org_estimate ON estimate_lines(organization_id,estimate_id);
CREATE INDEX IF NOT EXISTS idx_invoices_org_customer ON invoices(organization_id,customer_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_invoice_lines_org_invoice ON invoice_lines(organization_id,invoice_id);
CREATE TABLE IF NOT EXISTS contracts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, name TEXT NOT NULL, reference TEXT, starts_at TEXT NOT NULL, ends_at TEXT, sla_priority TEXT, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS asset_warranties (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, provider TEXT, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, terms TEXT, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS maintenance_plans (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, name TEXT NOT NULL, interval_days BIGINT NOT NULL CHECK(interval_days > 0), next_due_at TEXT NOT NULL, procedure_id TEXT REFERENCES procedure_definitions(id) ON DELETE SET NULL, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS maintenance_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, plan_id TEXT NOT NULL REFERENCES maintenance_plans(id) ON DELETE CASCADE, work_order_id TEXT REFERENCES work_orders(id) ON DELETE SET NULL, due_at TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(plan_id,due_at));
CREATE TABLE IF NOT EXISTS safety_checklists (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, work_type TEXT NOT NULL, items_json TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS safety_acknowledgements (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, checklist_id TEXT NOT NULL REFERENCES safety_checklists(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, answers_json TEXT NOT NULL, evidence_json TEXT NOT NULL DEFAULT '[]', measurements_json TEXT NOT NULL DEFAULT '{}', acknowledged_at TEXT NOT NULL, UNIQUE(checklist_id,work_order_id,actor_user_id));
CREATE INDEX IF NOT EXISTS idx_financials_org ON operational_financial_settings(organization_id);
CREATE INDEX IF NOT EXISTS idx_wo_financials_org ON work_order_financials(organization_id,updated_at);
CREATE INDEX IF NOT EXISTS idx_contracts_org_customer ON contracts(organization_id,customer_id,active);
CREATE INDEX IF NOT EXISTS idx_warranty_org_asset ON asset_warranties(organization_id,asset_id,active,ends_at);
CREATE INDEX IF NOT EXISTS idx_pm_org_due ON maintenance_plans(organization_id,active,next_due_at);
CREATE INDEX IF NOT EXISTS idx_pm_runs_org ON maintenance_runs(organization_id,due_at);
CREATE INDEX IF NOT EXISTS idx_safety_org ON safety_checklists(organization_id,active);
CREATE INDEX IF NOT EXISTS idx_safety_ack_org_wo ON safety_acknowledgements(organization_id,work_order_id,acknowledged_at);

-- Enterprise value additions (kept in canonical schema for parity checks)
CREATE TABLE IF NOT EXISTS approval_requests (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, entity_type text NOT NULL, entity_id TEXT NOT NULL, action text NOT NULL, reason text NOT NULL, status text NOT NULL CHECK(status IN ('pending','approved','rejected','cancelled')), requested_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, decided_by TEXT REFERENCES users(id) ON DELETE SET NULL, decision_reason text, created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS uq_approval_pending ON approval_requests(organization_id,entity_type,entity_id,action,status);
CREATE INDEX IF NOT EXISTS idx_approval_org_status ON approval_requests(organization_id,status,created_at);
CREATE TABLE IF NOT EXISTS inventory_ledger (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, part_id TEXT NOT NULL REFERENCES parts(id) ON DELETE RESTRICT, location_id TEXT NOT NULL REFERENCES inventory_locations(id) ON DELETE RESTRICT, work_order_id TEXT REFERENCES work_orders(id) ON DELETE SET NULL, source_type text NOT NULL, source_id text, quantity_delta integer NOT NULL, balance_after integer NOT NULL CHECK(balance_after >= 0), reason text NOT NULL, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_inventory_ledger_org_part ON inventory_ledger(organization_id,part_id,location_id,created_at);
CREATE TABLE IF NOT EXISTS business_calendars (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, timezone text NOT NULL, week_json jsonb NOT NULL, active boolean NOT NULL DEFAULT true, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_business_calendar_name ON business_calendars(organization_id,name);
CREATE TABLE IF NOT EXISTS business_calendar_exceptions (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, calendar_id TEXT NOT NULL REFERENCES business_calendars(id) ON DELETE CASCADE, date date NOT NULL, is_working boolean NOT NULL, start_minutes integer, end_minutes integer, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(calendar_id,date));
CREATE TABLE IF NOT EXISTS work_order_bulk_jobs (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, operation text NOT NULL, requested_count integer NOT NULL, affected_count integer NOT NULL DEFAULT 0, status text NOT NULL CHECK(status IN ('completed','partial','failed')), request_hash text NOT NULL, result_json jsonb NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_bulk_jobs_org_created ON work_order_bulk_jobs(organization_id,created_at);

-- Advanced enterprise value additions (kept in canonical schema for parity checks)
CREATE TABLE IF NOT EXISTS operational_configs (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, config_key text NOT NULL, config_value_json jsonb NOT NULL, version integer NOT NULL, status text NOT NULL CHECK(status IN ('draft','active','retired')), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, description text NOT NULL DEFAULT '', reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), activated_at timestamptz, UNIQUE(organization_id,config_key,version));
CREATE INDEX IF NOT EXISTS idx_operational_configs_active ON operational_configs(organization_id,config_key,status);

CREATE TABLE IF NOT EXISTS sync_conflicts (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, client_event_id text NOT NULL, entity_id text NOT NULL, operation text NOT NULL, payload_json jsonb NOT NULL, error_code text NOT NULL, retryable boolean NOT NULL, status text NOT NULL CHECK(status IN ('open','resolved','superseded')), resolution_json jsonb, resolved_by TEXT REFERENCES users(id) ON DELETE SET NULL, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_sync_conflicts_org_status ON sync_conflicts(organization_id,status,created_at);
CREATE UNIQUE INDEX IF NOT EXISTS uq_sync_conflict_event_error ON sync_conflicts(organization_id,actor_user_id,client_event_id,error_code);
CREATE TABLE IF NOT EXISTS time_entries (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, technician_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, appointment_id TEXT REFERENCES appointments(id) ON DELETE SET NULL, started_at timestamptz NOT NULL, ended_at timestamptz, status text NOT NULL CHECK(status IN ('running','stopped','void')), minutes integer CHECK(minutes IS NULL OR (minutes >= 1 AND minutes <= 1440)), note text NOT NULL DEFAULT '', source text NOT NULL DEFAULT 'manual', created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_time_entries_org_tech_status ON time_entries(organization_id,technician_id,status,started_at);
CREATE INDEX IF NOT EXISTS idx_time_entries_org_wo_started ON time_entries(organization_id,work_order_id,started_at);

CREATE UNIQUE INDEX IF NOT EXISTS uq_time_entry_running_technician ON time_entries(organization_id,technician_id) WHERE status='running';

CREATE TABLE IF NOT EXISTS first_time_right_checks (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, ready BIGINT NOT NULL CHECK(ready IN (0,1)), blockers_json TEXT NOT NULL, assessment_hash TEXT NOT NULL, checked_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, checked_at TEXT NOT NULL, UNIQUE(organization_id,work_order_id));
CREATE INDEX IF NOT EXISTS idx_first_time_right_org_ready ON first_time_right_checks(organization_id,ready,checked_at);

-- OpsCore v0.11.50 operational queue, line cutover and commercial reconciliation.
CREATE TABLE IF NOT EXISTS closure_sheets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, sheet_date TEXT NOT NULL, technician_id TEXT REFERENCES users(id) ON DELETE SET NULL, status TEXT NOT NULL CHECK(status IN ('ready','blocked')), item_count BIGINT NOT NULL DEFAULT 0 CHECK(item_count>=0), blocked_count BIGINT NOT NULL DEFAULT 0 CHECK(blocked_count>=0), sheet_sha256 TEXT NOT NULL, rows_json TEXT NOT NULL, compiled_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(organization_id,sheet_date,technician_id));
CREATE INDEX IF NOT EXISTS idx_closure_sheets_org_date ON closure_sheets(organization_id,sheet_date,status);
CREATE TABLE IF NOT EXISTS operational_jobs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, queue_name TEXT NOT NULL CHECK(queue_name IN ('support','billing','incident','general')), job_type TEXT NOT NULL, entity_type TEXT, entity_id TEXT, payload_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL CHECK(status IN ('queued','processing','completed','failed','dead_letter')), attempts BIGINT NOT NULL DEFAULT 0, max_attempts BIGINT NOT NULL DEFAULT 5 CHECK(max_attempts BETWEEN 1 AND 20), available_at TEXT NOT NULL, lease_until TEXT, last_error TEXT, result_json TEXT, created_by TEXT REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS operational_event_receipts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, event_key TEXT NOT NULL, event_type TEXT NOT NULL, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, payload_json TEXT NOT NULL, event_sha256 TEXT NOT NULL, observed_at TEXT NOT NULL, UNIQUE(organization_id,event_key));
CREATE INDEX IF NOT EXISTS idx_operational_event_receipts_org_observed ON operational_event_receipts(organization_id,observed_at);
CREATE INDEX IF NOT EXISTS idx_operational_jobs_queue ON operational_jobs(organization_id,queue_name,status,available_at,created_at);
CREATE INDEX IF NOT EXISTS idx_operational_jobs_lease ON operational_jobs(status,lease_until);
CREATE TABLE IF NOT EXISTS service_lines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, code TEXT NOT NULL, name TEXT NOT NULL, service_ref TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,code));
CREATE TABLE IF NOT EXISTS customer_service_lines (organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, line_id TEXT NOT NULL REFERENCES service_lines(id) ON DELETE RESTRICT, assigned_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(organization_id,customer_id));
CREATE INDEX IF NOT EXISTS idx_customer_service_lines_line ON customer_service_lines(organization_id,line_id);
CREATE TABLE IF NOT EXISTS line_migration_jobs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, from_line_id TEXT NOT NULL REFERENCES service_lines(id) ON DELETE RESTRICT, to_line_id TEXT NOT NULL REFERENCES service_lines(id) ON DELETE RESTRICT, status TEXT NOT NULL CHECK(status IN ('preflight','ready','running','completed','rolled_back','failed')), preflight_hash TEXT NOT NULL, before_hash TEXT, after_hash TEXT, rollback_json TEXT, error_code TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS uq_line_migration_active ON line_migration_jobs(organization_id,customer_id) WHERE status IN ('preflight','ready','running');
CREATE INDEX IF NOT EXISTS idx_line_migration_org_status ON line_migration_jobs(organization_id,status,created_at);
CREATE TABLE IF NOT EXISTS payment_reconciliation_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, provider TEXT NOT NULL CHECK(provider IN ('local','stripe')), scope_json TEXT NOT NULL, matched_count BIGINT NOT NULL, mismatch_count BIGINT NOT NULL, unmatched_count BIGINT NOT NULL, report_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('completed','failed')), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_recon_org_created ON payment_reconciliation_runs(organization_id,created_at);
CREATE TABLE IF NOT EXISTS invoice_payments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, amount NUMERIC(14,2) NOT NULL CHECK(amount > 0), source TEXT NOT NULL CHECK(source IN ('local_manual','stripe')), provider_reference TEXT, idempotency_key TEXT, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(organization_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_invoice_payments_org_invoice ON invoice_payments(organization_id,invoice_id,created_at);

CREATE TABLE IF NOT EXISTS agent_memories (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, memory_type TEXT NOT NULL, content_ciphertext TEXT NOT NULL, content_sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_agent_memories_subject ON agent_memories(organization_id,subject_type,subject_id,created_at);
CREATE TABLE IF NOT EXISTS tenant_domains (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, hostname TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('pending','verified','active','disabled')), verification_token TEXT NOT NULL, verified_at TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tenant_domains_org ON tenant_domains(organization_id,status);

CREATE TABLE IF NOT EXISTS operational_dependencies (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, depends_on_work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, dependency_type TEXT NOT NULL CHECK(dependency_type IN ('blocks','relates')), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(organization_id,work_order_id,depends_on_work_order_id,dependency_type), CHECK(work_order_id<>depends_on_work_order_id));
CREATE TABLE IF NOT EXISTS tenant_crypto_profiles (organization_id TEXT PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, key_version TEXT NOT NULL, algorithm TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parity_heartbeat_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('pass','degraded','fail')), checks_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_operational_dependencies_org_wo ON operational_dependencies(organization_id,work_order_id);
CREATE INDEX IF NOT EXISTS idx_parity_heartbeat_org_created ON parity_heartbeat_runs(organization_id,created_at);

CREATE TABLE IF NOT EXISTS geofences (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, geometry_json TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,name));
CREATE INDEX IF NOT EXISTS idx_geofences_org_enabled ON geofences(organization_id,enabled);
CREATE TABLE IF NOT EXISTS worker_guard_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, queue_name TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, metrics_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_worker_guard_events_org_created ON worker_guard_events(organization_id,created_at);
CREATE TABLE IF NOT EXISTS worker_guard_system_events (id TEXT PRIMARY KEY, queue_name TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, metrics_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_worker_guard_system_events_created ON worker_guard_system_events(created_at);

-- Final enterprise parity additions.
CREATE TABLE IF NOT EXISTS gateway_circuit_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, gateway_name text NOT NULL, state text NOT NULL CHECK(state IN ('closed','open','half-open')), failures integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gateway_circuit_events_org_gateway ON gateway_circuit_events(organization_id,gateway_name,created_at DESC);
CREATE TABLE IF NOT EXISTS signature_chain_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, document_type text NOT NULL, document_id text NOT NULL, level integer NOT NULL CHECK(level>0), signer_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, signer_role text NOT NULL DEFAULT 'member', payload_sha256 text NOT NULL, previous_hash text NOT NULL, chain_hash text NOT NULL, payload_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,document_type,document_id,level));
CREATE INDEX IF NOT EXISTS idx_signature_chain_doc ON signature_chain_events(organization_id,document_type,document_id,level);
CREATE TABLE IF NOT EXISTS billing_provider_registry (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, provider_name text NOT NULL, adapter_version text NOT NULL, enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,provider_name));
CREATE TABLE IF NOT EXISTS privacy_purge_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, summary_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());

CREATE INDEX IF NOT EXISTS idx_privacy_purge_runs_org_created ON privacy_purge_runs(organization_id,created_at);
CREATE TABLE IF NOT EXISTS technician_geofences (organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, geofence_id TEXT NOT NULL REFERENCES geofences(id) ON DELETE CASCADE, technician_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (organization_id,geofence_id,technician_id));
CREATE INDEX IF NOT EXISTS idx_technician_geofences_org_tech ON technician_geofences(organization_id,technician_id);
CREATE TABLE IF NOT EXISTS signature_chain_seals (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, document_type text NOT NULL, document_id text NOT NULL, final_chain_hash text NOT NULL, sealed_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, sealed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,document_type,document_id));
CREATE INDEX IF NOT EXISTS idx_signature_chain_seals_org_doc ON signature_chain_seals(organization_id,document_type,document_id);
CREATE TABLE IF NOT EXISTS gateway_circuit_states (organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, gateway_name TEXT NOT NULL, PRIMARY KEY (organization_id,gateway_name), status TEXT NOT NULL CHECK(status IN ('closed','open','half-open')), failures integer NOT NULL DEFAULT 0, opened_at bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS firewall_rate_buckets (bucket_key TEXT PRIMARY KEY, window_start bigint NOT NULL, requests bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
-- Platform Intelligence Layer (schema parity with SQLite migration 21).
CREATE TABLE IF NOT EXISTS operational_twin_snapshots (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, snapshot_kind TEXT NOT NULL CHECK(snapshot_kind IN ('on_demand','scenario')), state_json TEXT NOT NULL, state_sha256 TEXT NOT NULL, source_counts_json TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_twin_org_created ON operational_twin_snapshots(organization_id,created_at);
CREATE TABLE IF NOT EXISTS operational_twin_chain_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, sequence_no BIGINT NOT NULL CHECK (sequence_no > 0), event_type TEXT NOT NULL, snapshot_id TEXT NOT NULL, previous_hash TEXT NOT NULL CHECK (previous_hash = 'GENESIS' OR previous_hash ~ '^[0-9a-f]{64}$'), event_json TEXT NOT NULL, event_hash TEXT NOT NULL CHECK (event_hash ~ '^[0-9a-f]{64}$'), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,sequence_no), UNIQUE(organization_id,snapshot_id));
CREATE INDEX IF NOT EXISTS idx_twin_chain_org_sequence ON operational_twin_chain_events(organization_id,sequence_no);
CREATE TABLE IF NOT EXISTS decision_replays (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, decision_type TEXT NOT NULL, input_json TEXT NOT NULL, rules_json TEXT NOT NULL, outcome_json TEXT NOT NULL, decision_sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, replayed_at TEXT);
CREATE INDEX IF NOT EXISTS idx_decision_replays_org_created ON decision_replays(organization_id,created_at);
CREATE TABLE IF NOT EXISTS scenario_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, scenario_json TEXT NOT NULL, baseline_sha256 TEXT NOT NULL, result_json TEXT NOT NULL, result_sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_scenario_runs_org_created ON scenario_runs(organization_id,created_at);
CREATE TABLE IF NOT EXISTS skill_certifications (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill TEXT NOT NULL, certificate_ref TEXT NOT NULL, issuer TEXT NOT NULL, issued_at TEXT, expires_at TEXT, status TEXT NOT NULL CHECK(status IN ('active','expired','revoked')), evidence_sha256 TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,user_id,certificate_ref));
CREATE INDEX IF NOT EXISTS idx_skill_cert_org_user ON skill_certifications(organization_id,user_id,status,expires_at);
CREATE TABLE IF NOT EXISTS capacity_plans (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, plan_date TEXT NOT NULL, parameters_json TEXT NOT NULL, result_json TEXT NOT NULL, result_sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(organization_id,plan_date));
CREATE INDEX IF NOT EXISTS idx_capacity_plans_org_date ON capacity_plans(organization_id,plan_date);


-- Field Value Extensions: dynamic geofencing and OS-local sign-off assurance.
CREATE TABLE IF NOT EXISTS organization_governance (organization_id TEXT PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('active','read_only','suspended','closed')), reason TEXT NOT NULL DEFAULT '', changed_by TEXT REFERENCES users(id) ON DELETE SET NULL, changed_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS authorization_decisions (id TEXT PRIMARY KEY, organization_id TEXT, actor_user_id TEXT, role TEXT, source TEXT, correlation_id TEXT, operation_envelope_id TEXT, action TEXT NOT NULL, resource_type TEXT, resource_id TEXT, decision TEXT NOT NULL CHECK(decision IN ('allow','deny')), reason_code TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_authorization_decisions_org_created ON authorization_decisions(organization_id,created_at);
CREATE INDEX IF NOT EXISTS idx_authorization_decisions_org_resource ON authorization_decisions(organization_id,resource_type,resource_id);
CREATE TABLE IF NOT EXISTS operation_envelopes (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, role TEXT, source TEXT NOT NULL, correlation_id TEXT, causation_id TEXT, idempotency_key TEXT, operation TEXT NOT NULL, resource_type TEXT, resource_id TEXT, request_hash_sha256 TEXT, status TEXT NOT NULL CHECK(status IN ('started','committed','failed')), error_code TEXT, started_at TEXT NOT NULL, completed_at TEXT, UNIQUE(organization_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_operation_envelopes_org_started ON operation_envelopes(organization_id,started_at);
CREATE INDEX IF NOT EXISTS idx_operation_envelopes_correlation ON operation_envelopes(organization_id,correlation_id);
CREATE TABLE IF NOT EXISTS async_idempotency_reservations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, operation TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('started','committed','failed')), response_status INTEGER, response_json TEXT, operation_envelope_id TEXT REFERENCES operation_envelopes(id) ON DELETE SET NULL, started_at TEXT NOT NULL, completed_at TEXT, error_code TEXT, UNIQUE(organization_id,actor_user_id,operation,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_async_idempotency_status ON async_idempotency_reservations(organization_id,status,started_at);
CREATE TABLE IF NOT EXISTS configuration_change_log (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, config_id TEXT, config_key TEXT NOT NULL, version INTEGER NOT NULL, action TEXT NOT NULL CHECK(action IN ('created','activated')), actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, reason TEXT NOT NULL, correlation_id TEXT, request_hash_sha256 TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_configuration_change_log_org_key ON configuration_change_log(organization_id,config_key,created_at);

CREATE TABLE IF NOT EXISTS dynamic_geofence_events(
  id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  geofence_id TEXT REFERENCES geofences(id) ON DELETE CASCADE, source TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK(event_type IN ('hazard','restriction','clear')),
  severity TEXT NOT NULL CHECK(severity IN ('low','medium','high','critical')),
  latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL,
  radius_m DOUBLE PRECISION NOT NULL CHECK(radius_m > 0 AND radius_m <= 100000), reason TEXT NOT NULL,
  source_event_id TEXT, active_from TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL,
  event_sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_dynamic_geofence_org_active ON dynamic_geofence_events(organization_id,active_from,expires_at);
CREATE UNIQUE INDEX IF NOT EXISTS uq_dynamic_geofence_source_event ON dynamic_geofence_events(organization_id,source,source_event_id) WHERE source_event_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS field_signoff_assurance(
  id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  assurance_mode TEXT NOT NULL CHECK(assurance_mode IN ('os_local_biometric_gate','device_pin_gate','none')),
  verified_at TIMESTAMPTZ, client_reference TEXT, document_sha256 TEXT, metadata_json JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_field_signoff_assurance_org_wo ON field_signoff_assurance(organization_id,work_order_id,created_at);
